toad_implementation.code_blueprint:
canvas {
  size: 960px 650px;
  fill: #0A2540;
  font-family: "Consolas, monospace";
}

>cadBg = #0A2540;
>cadWhite = #FFFFFF;
>gridCyan = #173E6E;
>accentDim = #70A0D0;

rect #outerBorder {
  at: center of canvas;
  size: 900px 590px;
  fill: none;
  stroke: >cadWhite;
  stroke-width: 2px;
}

rect #componentMain {
  at: center of #outerBorder offset -60px -40px;
  size: 460px 260px;
  fill: none;
  stroke: >cadWhite;
  stroke-width: 3px;
}

rect #innerBoreHole {
  at: center of #componentMain;
  size: 140px 140px;
  fill: none;
  stroke: >cadWhite;
  stroke-width: 2px;
}

text #dimWidthLabel {
  at: top center of #componentMain offset 0px -28px;
  content: "◄  460.00 mm  ►";
  font-size: 13px;
  font-weight: 700;
  color: >cadWhite;
}

text #dimHeightLabel {
  at: right center of #componentMain offset 28px 0px;
  content: "▲ 260 mm ▼";
  font-size: 13px;
  font-weight: 700;
  color: >cadWhite;
}

rect #titleBlock {
  at: bottom right of #outerBorder;
  size: 320px 120px;
  fill: #081B30;
  stroke: >cadWhite;
  stroke-width: 2px;
}

text #docTitle {
  at: top left of #titleBlock offset 16px 16px;
  content: "TURBINE MOUNT HOUSING // CAD-DWG";
  font-size: 11px;
  font-weight: 700;
  color: >cadWhite;
}

text #docScale {
  at: below #docTitle offset 10px;
  content: "SCALE: 1:5  •  TOLERANCE: DIN ISO 2768-m";
  font-size: 10px;
  color: >accentDim;
}

text #docAuthor {
  at: below #docScale offset 8px;
  content: "ING.-BÜRO DR. V. RABE • REV 3.2";
  font-size: 10px;
  color: >accentDim;
}
